const item = $input.first();
const body = item.json.body || {};
let text = (body.text ?? '').toString();
let source_url = (body.source_url ?? body.sourceUrl ?? '').toString().trim();

/**
 * Shared text cleanup for kb-capture (Jina vacuum + OCR).
 * Used by unit tests; inlined into Prepare Capture Code node.
 */
function cleanExtractedText(raw) {
  if (raw == null) return '';
  let s = String(raw);
  if (!s.trim()) return '';

  // 1) script/style out entirely
  s = s.replace(/<script\b[\s\S]*?<\/script>/gi, ' ');
  s = s.replace(/<style\b[\s\S]*?<\/style>/gi, ' ');
  s = s.replace(/<noscript\b[\s\S]*?<\/noscript>/gi, ' ');

  // 2) unwrap strikethrough HTML (keep inner text)
  s = s.replace(/<(?:s|strike|del)\b[^>]*>([\s\S]*?)<\/(?:s|strike|del)>/gi, '$1');
  s = s.replace(/<\/?(?:s|strike|del)\b[^>]*>/gi, '');

  // 3) strip remaining HTML tags, keep text
  s = s.replace(/<!--[\s\S]*?-->/g, ' ');
  s = s.replace(/<\/?[a-zA-Z][^>]*>/g, ' ');

  // 4) markdown strikethrough ~~...~~ → keep text
  s = s.replace(/~~([^~\n]{0,400})~~/g, '$1');

  // 5) zero-width / BOM / soft hyphen junk
  s = s.replace(/[\u200B-\u200D\uFEFF\u00AD]/g, '');

  // 6) orphan bracket tags like [/...] leftover from broken markup
  s = s.replace(/\[\/[^\]]{0,60}\]/g, ' ');
  // leftover bare angle fragments that aren't real words
  s = s.replace(/<\/?[a-zA-Z][^>\n]{0,40}>/g, ' ');

  // 7) Jina Reader chrome — prefer body after "Markdown Content:"
  const mdMatch = s.match(/^Markdown Content:\s*/im);
  if (mdMatch && typeof mdMatch.index === 'number') {
    const titleMatch = s.match(/^Title:\s*(.+)$/m);
    const title = titleMatch ? titleMatch[1].trim() : '';
    s = s.slice(mdMatch.index + mdMatch[0].length);
    if (title) {
      const head = s.trim().slice(0, Math.min(60, title.length));
      if (!title.startsWith(head) && !s.trim().startsWith('#')) {
        s = title + '\n\n' + s;
      }
    }
  } else {
    s = s.replace(/^(Title|URL Source|Published Time|Markdown Content):\s*.*$/gim, '');
  }

  const BANNER_PHRASE =
    /accepter (les |tous les )?cookies|accept(\s+all)?\s+cookies|reject\s+all|manage (cookie )?preferences|nous utilisons des cookies|this site uses cookies|privacy center|consent management|cookiebot|onetrust|didomi|politique de confidentialit[eé]|privacy policy|tracking technologies|adchoices|gestion des cookies|param[eè]tres (des |de )?cookies/i;

  const CONSENT_TOKEN =
    /cookies?|consentement|consent|accepter|accept all|reject all|manage preferences|politique de confidentialit[eé]|privacy policy|nous utilisons des cookies|this site uses cookies|\bGDPR\b|\bRGPD\b|OneTrust|Cookiebot|Didomi|consent management|privacy center|tracking technologies|essential cookies|targeted advertising|adchoices|social media services|core website features|gestion des cookies|pr[eé]f[eé]rences/gi;

  const CMP_HEADER =
    /^(Privacy Center|Social Media|Essential|Targeted|Performance|Functional|Marketing|Strictly Necessary|Cookie Settings|Manage Consent|Gestion des cookies|Centre de confidentialit[eé]|Pr[eé]f[eé]rences de cookies)$/i;

  function consentScore(p) {
    const m = p.match(CONSENT_TOKEN);
    return m ? m.length : 0;
  }

  // 8) drop consent-heavy paragraphs (blocks, not every "cookie" mention)
  function isConsentBlock(t) {
    if (!t) return false;
    if (CMP_HEADER.test(t) && t.length < 80) return true;
    if (BANNER_PHRASE.test(t) && t.length < 1200) return true;
    const score = consentScore(t);
    // heavy consent vocabulary → block
    if (score >= 2) return true;
    // short banner-like blurbs with classic consent phrasing
    if (score >= 1 && t.length < 280 && BANNER_PHRASE.test(t)) return true;
    return false;
  }

  let paras = s.split(/\n\s*\n+/);
  paras = paras.filter((p) => !isConsentBlock(p.trim()));

  // drop leading short CMP chrome (headers / toggle rows) at document start
  while (paras.length) {
    const t = paras[0].trim();
    if (!t) {
      paras.shift();
      continue;
    }
    if (CMP_HEADER.test(t)) {
      paras.shift();
      continue;
    }
    if (isConsentBlock(t)) {
      paras.shift();
      continue;
    }
    if (/^(- \[[ xX]\]\s*On\s*)+$/m.test(t)) {
      paras.shift();
      continue;
    }
    break;
  }

  s = paras.join('\n\n');

  // line-level CMP chrome
  s = s
    .split('\n')
    .filter((line) => {
      const t = line.trim();
      if (!t) return true;
      if (/^- \[[ xX]\]\s*On\s*$/.test(t)) return false;
      if (/^\*\s*\*\s*\*$/.test(t) || /^\*{3,}$/.test(t)) return false;
      if (CMP_HEADER.test(t)) return false;
      if (BANNER_PHRASE.test(t) && t.length < 220) return false;
      return true;
    })
    .join('\n');

  // 9) whitespace normalize
  s = s.replace(/[ \t]+/g, ' ');
  s = s.replace(/ *\n */g, '\n');
  s = s.replace(/\n{3,}/g, '\n\n');
  return s.trim();
}

// Avoid `new URL()` — unavailable / unreliable in some n8n Code sandboxes.
if (!/^https?:\/\/[^\s<>"{}|\\^`[\]]+$/i.test(source_url)) {
  source_url = '';
} else {
  source_url = source_url.replace(/[.,);]+$/g, '');
}

const bin = item.binary || {};
let has_image = false;
for (const key of Object.keys(bin)) {
  const b = bin[key];
  if (b && b.mimeType && String(b.mimeType).startsWith('image/')) {
    has_image = true;
    break;
  }
}
if (!has_image) {
  for (const key of Object.keys(bin)) {
    if (bin[key] && bin[key].data) {
      has_image = true;
      break;
    }
  }
}

if (!text && !source_url && !has_image) {
  throw new Error('Need at least one of: text, source_url, or image file');
}

let full_text_raw = '';
let full_text = '';
let vacuum_ok = false;
let vacuum_error = '';
if (source_url) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://r.jina.ai/' + source_url,
      headers: {
        Accept: 'text/plain',
        'User-Agent': 'kb-capture/1.0',
      },
      timeout: 20000,
    });
    full_text_raw = typeof res === 'string' ? res : String(res ?? '');
    full_text = cleanExtractedText(full_text_raw);
    vacuum_ok = full_text.trim().length >= 80;
    if (!vacuum_ok) vacuum_error = 'vacuum_too_short';
  } catch (e) {
    full_text_raw = '';
    full_text = '';
    vacuum_ok = false;
    vacuum_error = (e && e.message) ? String(e.message).slice(0, 200) : 'vacuum_failed';
  }
}

const text_clean = cleanExtractedText(text);
// --- Transcript extraction (YouTube + generic page heuristic + Apify fallback) ---
function detectMediaPlatform(url) {
  const u = String(url || '').toLowerCase();
  if (!u) return '';
  if (/youtube\.com|youtu\.be|youtube-nocookie\.com/.test(u)) return 'youtube';
  if (/tiktok\.com/.test(u)) return 'tiktok';
  if (/instagram\.com/.test(u)) return 'instagram';
  return '';
}

function extractYoutubeVideoId(url) {
  const u = String(url || '');
  let m = u.match(/[?&]v=([A-Za-z0-9_-]{6,})/);
  if (m) return m[1];
  m = u.match(/youtu\.be\/([A-Za-z0-9_-]{6,})/);
  if (m) return m[1];
  m = u.match(/\/shorts\/([A-Za-z0-9_-]{6,})/);
  if (m) return m[1];
  m = u.match(/\/embed\/([A-Za-z0-9_-]{6,})/);
  if (m) return m[1];
  m = u.match(/\/live\/([A-Za-z0-9_-]{6,})/);
  if (m) return m[1];
  return '';
}

function decodeHtmlEntities(s) {
  return String(s || '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, h) => String.fromCharCode(parseInt(h, 16)));
}

function parseTimedTextXml(xml) {
  const texts = [];
  const re = /<text[^>]*>([\s\S]*?)<\/text>|<p[^>]*>([\s\S]*?)<\/p>/gi;
  let m;
  while ((m = re.exec(String(xml || '')))) {
    const raw = m[1] != null ? m[1] : m[2];
    const t = decodeHtmlEntities(String(raw).replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
    if (t) texts.push(t);
  }
  return texts.join(' ').replace(/\s+/g, ' ').trim();
}

function parseJson3Captions(raw) {
  try {
    const data = typeof raw === 'string' ? JSON.parse(raw) : raw;
    const events = data.events || [];
    const parts = [];
    for (const ev of events) {
      if (!ev || !Array.isArray(ev.segs)) continue;
      for (const seg of ev.segs) {
        if (seg && typeof seg.utf8 === 'string') parts.push(seg.utf8);
      }
    }
    return parts.join('').replace(/\s+/g, ' ').trim();
  } catch (e) {
    return '';
  }
}

function extractTranscriptFromPageText(text) {
  const s = String(text || '');
  if (!s.trim()) return { found: false, transcript: '', reason: 'empty' };

  // Explicit transcript / captions section
  const sectionRe = /(?:^|\n)#{1,3}\s*(transcript|transcription|captions?|sous-titres?|transcripci[oó]n)\b[^\n]*\n+([\s\S]{200,})/i;
  const sec = s.match(sectionRe);
  if (sec) {
    let body = sec[2];
    const cut = body.search(/\n#{1,3}\s+\S/);
    if (cut > 200) body = body.slice(0, cut);
    body = body.trim();
    if (body.length >= 200) {
      return { found: true, transcript: body.slice(0, 50000), reason: 'page_section' };
    }
  }

  // Dialogue-like density: many short lines with speaker cues or timestamps
  const lines = s.split(/\n/).map((l) => l.trim()).filter(Boolean);
  const dialogueLines = lines.filter((l) =>
    /^(\[?\d{1,2}:\d{2}(:\d{2})?\]?|[A-ZÀ-Ÿ][\wÀ-ÿ.'-]{0,30}\s*:|[-–—]\s+\S)/.test(l) &&
    l.length < 220
  );
  if (dialogueLines.length >= 12 && dialogueLines.join(' ').length >= 400) {
    return {
      found: true,
      transcript: dialogueLines.join('\n').slice(0, 50000),
      reason: 'page_dialogue',
    };
  }

  // Long vacuum that looks like spoken prose (YouTube description dumps rarely this long alone)
  const words = s.split(/\s+/).filter(Boolean);
  if (words.length >= 350) {
    const sentenceEnds = (s.match(/[.!?]["')\]]?\s+[A-ZÀ-Ÿ]/g) || []).length;
    if (sentenceEnds >= 20) {
      // Likely article body, not necessarily a transcript — do not claim transcript
      return { found: false, transcript: '', reason: 'long_prose_not_transcript' };
    }
  }

  return { found: false, transcript: '', reason: 'not_found_in_page' };
}

async function fetchYoutubeCaptionsViaInnertube(videoId) {
  const player = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://www.youtube.com/youtubei/v1/player?prettyPrint=false',
    headers: {
      'Content-Type': 'application/json',
      'User-Agent': 'com.google.android.youtube/20.10.38 (Linux; U; Android 14) gzip',
    },
    body: {
      context: { client: { clientName: 'ANDROID', clientVersion: '20.10.38' } },
      videoId,
    },
    json: true,
    timeout: 25000,
  });

  const tracks =
    (((player || {}).captions || {}).playerCaptionsTracklistRenderer || {}).captionTracks ||
    [];
  if (!tracks.length) return { ok: false, text: '', error: 'no_caption_tracks' };

  // Prefer manual tracks, then en/fr, then first
  const ranked = [...tracks].sort((a, b) => {
    const score = (t) => {
      let s = 0;
      if (!t.kind || t.kind !== 'asr') s += 5;
      const lang = String(t.languageCode || '').toLowerCase();
      if (lang.startsWith('fr')) s += 4;
      if (lang.startsWith('en')) s += 3;
      return s;
    };
    return score(b) - score(a);
  });

  for (const track of ranked.slice(0, 4)) {
    const base = track.baseUrl;
    if (!base) continue;
    for (const fmt of ['json3', 'srv3', '']) {
      try {
        const url = fmt ? base + (base.includes('?') ? '&' : '?') + 'fmt=' + fmt : base;
        const raw = await this.helpers.httpRequest({
          method: 'GET',
          url,
          headers: { 'User-Agent': 'Mozilla/5.0 kb-capture/1.0' },
          timeout: 20000,
        });
        const body = typeof raw === 'string' ? raw : String(raw ?? '');
        if (!body || body.length < 40) continue;
        let text = '';
        if (fmt === 'json3' || body.trim().startsWith('{')) {
          text = parseJson3Captions(body);
          if (!text) text = parseTimedTextXml(body);
        } else {
          text = parseTimedTextXml(body);
        }
        if (text && text.length >= 40) {
          return {
            ok: true,
            text: text.slice(0, 50000),
            lang: track.languageCode || '',
            error: '',
          };
        }
      } catch (e) {
        // try next format / track
      }
    }
  }
  return { ok: false, text: '', error: 'caption_fetch_empty' };
}

async function fetchYoutubeTranscriptViaApify(videoUrl) {
  let token = '';
  try {
    if (typeof $env !== 'undefined' && $env.APIFY_TOKEN) token = String($env.APIFY_TOKEN);
  } catch (e) {}
  try {
    if (!token && typeof process !== 'undefined' && process.env && process.env.APIFY_TOKEN) {
      token = String(process.env.APIFY_TOKEN);
    }
  } catch (e) {}
  if (!token) return { ok: false, text: '', error: 'apify_token_missing' };

  try {
    const items = await this.helpers.httpRequest({
      method: 'POST',
      url:
        'https://api.apify.com/v2/acts/' +
        'pintostudio~youtube-transcript-scraper' +
        '/run-sync-get-dataset-items',
      headers: {
        'Content-Type': 'application/json',
        Authorization: 'Bearer ' + token,
      },
      body: { videoUrl, targetLanguage: 'en' },
      json: true,
      timeout: 120000,
    });
    const list = Array.isArray(items) ? items : [];
    const parts = [];
    for (const it of list) {
      if (!it || typeof it !== 'object') continue;
      if (typeof it.text === 'string') parts.push(it.text);
      else if (typeof it.transcript === 'string') parts.push(it.transcript);
      else if (typeof it.caption === 'string') parts.push(it.caption);
      else if (Array.isArray(it.transcript)) {
        for (const row of it.transcript) {
          if (typeof row === 'string') parts.push(row);
          else if (row && typeof row.text === 'string') parts.push(row.text);
        }
      } else if (Array.isArray(it.data)) {
        for (const row of it.data) {
          if (row && typeof row.text === 'string') parts.push(row.text);
        }
      }
    }
    const text = parts.join(' ').replace(/\s+/g, ' ').trim();
    if (text.length >= 40) return { ok: true, text: text.slice(0, 50000), error: '' };
    return { ok: false, text: '', error: 'apify_empty' };
  } catch (e) {
    return {
      ok: false,
      text: '',
      error: (e && e.message) ? String(e.message).slice(0, 200) : 'apify_failed',
    };
  }
}

const media_platform = detectMediaPlatform(source_url);
let transcript = '';
let transcript_source = '';
let transcript_error = '';
let transcript_lang = '';

function transcriptLooksClean(t) {
  const s = String(t || '');
  if (s.length < 40) return false;
  // YouTube/Jina chrome — NOT spoken "subscribe" (common outro in real captions)
  if (/ytimg\.com|hqdefault|NaN\s*\/\s*NaN|!\[Image\s*\d+|watching on YouTube|Skip navigation|Search with your voice/i.test(s)) return false;
  const words = s.split(/\s+/).filter(Boolean);
  if (words.length < 12) return false;
  const urls = (s.match(/https?:\/\//g) || []).length;
  if (urls >= 3 && urls * 40 > words.length) return false;
  const mdImgs = (s.match(/!\[[^\]]*\]\(/g) || []).length;
  if (mdImgs >= 2) return false;
  return true;
}

/** Collapse consecutive / rolling-caption duplicates without deleting unique dialogue. */
function cleanTranscriptText(raw) {
  let s = String(raw || '').replace(/\r\n/g, '\n').trim();
  if (!s) return '';

  // Prefer line-oriented cleaning when there are multiple non-empty lines
  let lines = s.split(/\n/).map((l) => l.replace(/\s+/g, ' ').trim()).filter(Boolean);
  if (lines.length <= 1) {
    // Prose / space-joined captions: split into sentences then collapse
    lines = s
      .replace(/\s+/g, ' ')
      .split(/(?<=[.!?])\s+/)
      .map((l) => l.trim())
      .filter(Boolean);
  }

  function norm(x) {
    return String(x || '')
      .toLowerCase()
      .replace(/[^\p{L}\p{N}\s]/gu, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function isNearDup(a, b) {
    const na = norm(a);
    const nb = norm(b);
    if (!na || !nb) return false;
    if (na === nb) return true;
    // Rolling ASR: one segment contained in the next (or vice versa)
    const shorter = na.length <= nb.length ? na : nb;
    const longer = na.length <= nb.length ? nb : na;
    if (shorter.length >= 12 && longer.includes(shorter)) return true;
    // Shared long prefix (karaoke-style updates)
    const n = Math.min(na.length, nb.length, 80);
    if (n >= 24) {
      let same = 0;
      for (let i = 0; i < n; i++) {
        if (na[i] === nb[i]) same++;
        else break;
      }
      if (same / n >= 0.82) return true;
    }
    return false;
  }

  const out = [];
  for (const line of lines) {
    if (!out.length) {
      out.push(line);
      continue;
    }
    const prev = out[out.length - 1];
    if (isNearDup(prev, line)) {
      // Keep the longer / more complete variant
      if (line.length > prev.length) out[out.length - 1] = line;
      continue;
    }
    out.push(line);
  }

  let cleaned = out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
  // If original was single-paragraph prose, rejoin with spaces
  if (!/\n/.test(String(raw || '').trim()) || String(raw || '').split(/\n/).filter((l) => l.trim()).length <= 1) {
    cleaned = out.join(' ').replace(/\s+/g, ' ').trim();
  }
  return cleaned.slice(0, 50000);
}

const pageProbe = extractTranscriptFromPageText(full_text || text_clean);
const pageOk = pageProbe.found && transcriptLooksClean(pageProbe.transcript);

if (media_platform === 'youtube') {
  const videoId = extractYoutubeVideoId(source_url);
  if (videoId) {
    try {
      const cap = await fetchYoutubeCaptionsViaInnertube.call(this, videoId);
      if (cap.ok && transcriptLooksClean(cap.text)) {
        transcript = cap.text;
        transcript_source = 'youtube_innertube';
        transcript_lang = cap.lang || '';
      } else {
        if (cap && cap.ok && !transcriptLooksClean(cap.text)) {
          transcript_error = 'innertube_rejected_as_chrome';
        } else {
          transcript_error = (cap && cap.error) ? cap.error : 'innertube_failed';
        }
        const ap = await fetchYoutubeTranscriptViaApify.call(this, source_url);
        if (ap.ok && transcriptLooksClean(ap.text)) {
          transcript = ap.text;
          transcript_source = 'apify_pintostudio';
          transcript_error = '';
        } else {
          const apErr = (ap && ap.ok && !transcriptLooksClean(ap.text))
            ? 'apify_rejected_as_chrome'
            : ((ap && ap.error) || 'apify_failed');
          transcript_error = (transcript_error ? transcript_error + ';' : '') + apErr;
          if (pageOk) {
            transcript = pageProbe.transcript;
            transcript_source = pageProbe.reason;
            transcript_error = '';
          }
        }
      }
    } catch (e) {
      transcript_error = (e && e.message) ? String(e.message).slice(0, 200) : 'transcript_failed';
      try {
        const ap = await fetchYoutubeTranscriptViaApify.call(this, source_url);
        if (ap.ok && transcriptLooksClean(ap.text)) {
          transcript = ap.text;
          transcript_source = 'apify_pintostudio';
          transcript_error = '';
        } else if (pageOk) {
          transcript = pageProbe.transcript;
          transcript_source = pageProbe.reason;
          transcript_error = '';
        } else if (ap && ap.error) {
          transcript_error += ';' + ap.error;
        }
      } catch (e2) {
        if (pageOk) {
          transcript = pageProbe.transcript;
          transcript_source = pageProbe.reason;
          transcript_error = '';
        }
      }
    }
  } else {
    transcript_error = 'youtube_id_missing';
    if (pageOk) {
      transcript = pageProbe.transcript;
      transcript_source = pageProbe.reason;
      transcript_error = '';
    }
  }
} else if (pageOk) {
  transcript = pageProbe.transcript;
  transcript_source = pageProbe.reason;
} else if (source_url && pageProbe.reason) {
  transcript_error = pageProbe.reason;
}

function stripTranscriptSections(text) {
  let s = String(text || '');
  s = s.replace(/(?:^|\n)#{1,3}\s*(?:transcript|transcription|captions?|sous-titres?|transcripci[oó]n)\b[^\n]*\n[\s\S]*?(?=\n#{1,3}\s+\S|$)/gi, '\n');
  return s.replace(/\n{3,}/g, '\n\n').trim();
}

function sanitizeYoutubeVacuum(text) {
  let s = stripTranscriptSections(text);
  // Drop Comments / Chapters chrome blocks entirely
  s = s.replace(/(?:^|\n)#{1,3}\s*(?:Comments?|Chapters?|Shorts|Live chats?)\b[^\n]*\n[\s\S]*?(?=\n#{1,3}\s+\S|$)/gi, '\n');

  // Prefer Title + Description when present (real page content for YT)
  const descMatch = s.match(/(?:^|\n)#{1,3}\s*Description\b[^\n]*\n+([\s\S]+?)(?=\n#{1,3}\s+\S|$)/i);
  if (descMatch && descMatch[1].trim().length >= 60) {
    const lines = s.split('\n').map((l) => l.trim()).filter(Boolean);
    let title = '';
    for (const l of lines.slice(0, 12)) {
      if (/^#{1,3}\s/.test(l)) continue;
      if (/^!\[|^\[|https?:\/\//i.test(l)) continue;
      if (/^(back|search|sign in)$/i.test(l)) continue;
      if (l.length >= 12 && l.length <= 160) {
        title = l;
        break;
      }
    }
    let desc = descMatch[1].trim();
    // Cut description before related-video link farms
    const farm = desc.search(/\n(?=###?\s*\[|!\[[^\]]*\]\(https?:\/\/(?:www\.)?youtube\.com\/watch)/i);
    if (farm > 80) desc = desc.slice(0, farm).trim();
    return (title ? title + '\n\n' : '') + desc;
  }

  const lines = s.split('\n');
  const out = [];
  let prevNorm = '';
  let consec = 0;
  let selfUrlHits = 0;
  for (const line of lines) {
    const t = line.trim();
    if (!t) {
      out.push(line);
      continue;
    }
    if (/^(skip navigation|search with your voice|sign in|subscribe|back|show more|show less)$/i.test(t)) continue;
    if (/ytimg\.com|hqdefault/i.test(t)) continue;
    if (/^!\[[^\]]*\]\(https?:\/\/[^)]+\)/i.test(t) && /watch\?v=/i.test(t)) continue;
    if (/youtube\.com\/watch\?v=/i.test(t)) {
      selfUrlHits += 1;
      if (selfUrlHits > 2) continue;
    }
    const norm = t.toLowerCase().replace(/\s+/g, ' ');
    if (norm && norm === prevNorm) {
      consec += 1;
      if (consec >= 1) continue;
    } else {
      consec = 0;
      prevNorm = norm;
    }
    out.push(line);
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

if (transcript) {
  transcript = cleanTranscriptText(transcript);
}

const transcript_ok = !!(transcript && transcript.trim().length >= 40);

// Prefer feeding LLM a mix of page + transcript when useful
// Use sanitized body head for YouTube to avoid chrome drowning the LLM
let content_for_llm = (
  vacuum_ok ? full_text : (text_clean || source_url || 'capture sans texte')
);
if (media_platform === 'youtube') {
  content_for_llm = sanitizeYoutubeVacuum(content_for_llm) || content_for_llm;
}
if (transcript_ok) {
  const head = stripTranscriptSections(content_for_llm).slice(0, 6000);
  const tr = transcript.slice(0, 6000);
  content_for_llm = (head + '\n\n## Transcript\n\n' + tr).slice(0, 12000);
} else {
  content_for_llm = stripTranscriptSections(content_for_llm).slice(0, 12000);
}

let body_content = vacuum_ok ? full_text : text_clean;
// Always remove fake ## Transcript chrome from vacuum (even when captions fail)
if (media_platform === 'youtube') {
  body_content = sanitizeYoutubeVacuum(body_content);
} else if (/##\s*Transcript\b/i.test(body_content || '')) {
  body_content = stripTranscriptSections(body_content);
}
if (transcript_ok) {
  body_content = stripTranscriptSections(body_content);
  if (!body_content) body_content = transcript;
}

return [{
  json: {
    text: text_clean,
    text_raw: text,
    source_url,
    has_image,
    full_text,
    full_text_raw,
    full_text_clean: full_text,
    vacuum_ok,
    vacuum_error,
    content_for_llm,
    body_content,
    media_platform,
    transcript: transcript_ok ? transcript : '',
    transcript_ok,
    transcript_source,
    transcript_error,
    transcript_lang,
  },
  binary: item.binary,
}];

