parameters.jsCode:
const item = $input.first();
const prep = $('Prepare Capture').first().json;

let parsed = {};
try {
  const raw = item.json.choices?.[0]?.message?.content;
  parsed = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});
} catch (e) {
  parsed = {};
}

const SOFT_MAP = {
  'mystère littéraire': 'littérature',
  'mystere litteraire': 'littérature',
  'romand interactif': 'littérature',
  'roman interactif': 'littérature',
  'the new york times': 'NYT',
  'new york times': 'NYT',
  'new yorker': 'New Yorker',
};

function softMap(s) {
  const k = String(s || '').trim().toLowerCase().replace(/\s+/g, ' ');
  return SOFT_MAP[k] || null;
}

function isProperish(s) {
  return /^@/.test(s) || /[A-ZÀ-Ÿ]/.test(s) || /\./.test(s);
}

function polishTopic(tag) {
  let t = String(tag || '').trim().replace(/^#/, '');
  if (!t) return '';
  const mapped = softMap(t);
  if (mapped) return mapped;
  const words = t.split(/\s+/).filter(Boolean);
  if (words.length > 3) {
    const first = softMap(words.slice(0, 2).join(' ')) || softMap(words[0]) || words[0];
    t = first;
  }
  if (/cookie|consent|rgpd|gdpr|onetrust|cookiebot/i.test(t)) return '';
  if (!isProperish(t)) t = t.toLowerCase();
  return t.slice(0, 48);
}

function polishFacet(s, { allowAt = true } = {}) {
  let t = String(s || '').trim();
  if (!t || /^n\/?a$/i.test(t) || /^unknown$/i.test(t) || /^inconnu$/i.test(t)) return '';
  const mapped = softMap(t);
  if (mapped) return mapped;
  if (allowAt && /^instagram\.com\/([^/?#]+)/i.test(t)) {
    return '@' + t.match(/instagram\.com\/([^/?#]+)/i)[1];
  }
  const words = t.split(/\s+/);
  if (words.length > 4 && !/^@/.test(t)) {
    const m = softMap(t) || softMap(words.slice(0, 3).join(' '));
    if (m) return m;
  }
  return t.slice(0, 60);
}

let tags = Array.isArray(parsed.tags) ? parsed.tags.map(polishTopic).filter(Boolean) : [];
const seen = new Set();
tags = tags.filter((t) => {
  const k = t.toLowerCase();
  if (seen.has(k)) return false;
  seen.add(k);
  return true;
}).slice(0, 7);

function mediumFromUrl(url) {
  const u = String(url || '');
  const m = u.match(/^https?:\/\/([^\/?#]+)/i);
  if (!m) return '';
  const host = m[1].toLowerCase().replace(/^www\./, '');
  const path = (u.split(host)[1] || '').split(/[?#]/)[0] || '';
  const HOST_MAP = {
    'nytimes.com': 'NYT',
    'www.nytimes.com': 'NYT',
    'newyorker.com': 'New Yorker',
    'wired.com': 'Wired',
    'lemonde.fr': 'Le Monde',
    'linkedin.com': 'LinkedIn',
    'x.com': 'X',
    'twitter.com': 'X',
    'youtube.com': 'YouTube',
    'youtu.be': 'YouTube',
    'substack.com': 'Substack',
    'medium.com': 'Medium.com',
  };
  if (HOST_MAP[host]) return HOST_MAP[host];
  if (host === 'instagram.com' || host.endsWith('.instagram.com')) {
    const h = path.match(/^\/@?([A-Za-z0-9._]+)/);
    return h ? '@' + h[1] : 'Instagram';
  }
  if (host === 'tiktok.com') {
    const h = path.match(/^\/@([A-Za-z0-9._]+)/);
    return h ? '@' + h[1] : 'TikTok';
  }
  const sub = host.match(/^([a-z0-9-]+)\.substack\.com$/);
  if (sub) return sub[1] + ' (Substack)';
  const label = host.split('.')[0];
  if (label && label.length >= 2 && label !== 'www') {
    return label.charAt(0).toUpperCase() + label.slice(1);
  }
  return '';
}

const author = polishFacet(parsed.author || '', { allowAt: false });
const llmMedium = polishFacet(
  parsed.medium || parsed.outlet || parsed.publication || '',
  { allowAt: true }
);
const urlMedium = mediumFromUrl(prep.source_url || '');
let medium = urlMedium || llmMedium;
if (/^(article|post|vid[eé]o|podcast|newsletter|thread|screenshot)$/i.test(medium) && urlMedium) {
  medium = urlMedium;
}
const format = polishFacet(parsed.format || '', { allowAt: false }).toLowerCase();

// Strip facet echoes from topic tags (Tags = subjects only)
const facetKeys = new Set(
  [author, medium, format].filter(Boolean).map((x) => x.toLowerCase())
);
tags = tags.filter((t) => !facetKeys.has(t.toLowerCase()));

const title = (parsed.title || 'capture').toString().trim().slice(0, 200) || 'capture';
const summary = (parsed.summary || '').toString().trim();
let filename = (parsed.filename || '').toString().trim();
if (!filename) {
  filename = 'capture-' + new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
}
filename = filename.replace(/[^a-zA-Z0-9_-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80) || 'capture';

return [{
  json: {
    title,
    summary,
    tags,
    tags_topic: tags,
    author,
    medium,
    format,
    ocr: prep.text || '',
    filename,
    source_url: prep.source_url || '',
    full_text: prep.full_text || '',
    full_text_raw: prep.full_text_raw || '',
    vacuum_ok: !!prep.vacuum_ok,
    body_content: prep.body_content || '',
    has_image: !!prep.has_image,
    media_platform: prep.media_platform || '',
    transcript: prep.transcript || '',
    transcript_ok: !!prep.transcript_ok,
    transcript_source: prep.transcript_source || '',
    transcript_error: prep.transcript_error || '',
    transcript_lang: prep.transcript_lang || '',
  },
}];

const fs = require('fs');
const path = require('path');

const input = $input.first();
const base = input.json;
const wh = $('Webhook').first();
const bin = wh.binary || {};

let binaryData = null;
for (const key of Object.keys(bin)) {
  const b = bin[key];
  if (b && b.data && b.mimeType && b.mimeType.startsWith('image/')) {
    binaryData = b;
    break;
  }
}
if (!binaryData) {
  for (const key of Object.keys(bin)) {
    if (bin[key] && bin[key].data) {
      binaryData = bin[key];
      break;
    }
  }
}

if (!binaryData || !binaryData.data) {
  return [{
    json: {
      ...base,
      has_image: false,
      saved_to: '',
      file_size: 0,
      kdrive_url: '',
    },
  }];
}

const filename = base.filename;
if (!filename) {
  throw new Error('No filename produced by the AI step.');
}

const dir = '/home/ubuntu/n8n/media';
const filepath = path.join(dir, filename + '.png');
fs.mkdirSync(dir, { recursive: true });
const buf = Buffer.from(binaryData.data, 'base64');
fs.writeFileSync(filepath, buf);

return [{
  json: {
    ...base,
    has_image: true,
    saved_to: filepath,
    file_size: buf.length,
  },
  binary: { data: binaryData },
}];

const notion = $input.first().json;

function tryNode(name) {
  try {
    return $(name).first().json;
  } catch (e) {
    return null;
  }
}

const meta = tryNode('Enrich With Media') || tryNode('Enrich Without Media') || {};

const source_url = meta.source_url || '';
const body_content = meta.body_content || meta.ocr || '';
const tags = Array.isArray(meta.tags) ? meta.tags : [];
const tags_topic = Array.isArray(meta.tags_topic) ? meta.tags_topic : tags;
const title = meta.title || notion.name || 'capture';
const summary = meta.summary || '';
const ocr = meta.ocr || '';
const filename = meta.filename || '';
const has_image = !!meta.has_image;
const kdrive_url = meta.kdrive_url || '';
const vacuum_ok = !!meta.vacuum_ok;
const author = meta.author || '';
const medium = meta.medium || meta.outlet || '';
const format = meta.format || '';
const transcript = meta.transcript || '';
const transcript_ok = !!meta.transcript_ok;
const transcript_source = meta.transcript_source || '';

const fmSource = source_url || (has_image ? 'screenshot' : 'share');
const tagsMd = tags_topic.map(t => '  - ' + t).join('\n');
let md = '---\n';
md += 'source: ' + fmSource + '\n';
md += 'created: ' + new Date().toISOString() + '\n';
if (author) md += 'author: ' + JSON.stringify(author) + '\n';
if (medium) md += 'medium: ' + JSON.stringify(medium) + '\n';
if (format) md += 'format: ' + JSON.stringify(format) + '\n';
md += 'tags:\n' + tagsMd + '\n';
md += '---\n\n';
md += '# ' + title + '\n\n';
if (source_url) {
  md += '[Page originale](' + source_url + ')\n\n';
}
md += '## Summary\n\n' + summary + '\n\n';
function stripTranscriptSectionsMd(text) {
  let s = String(text || '');
  s = s.replace(/(?:^|\n)#{1,3}\s*(?:transcript|transcription|captions?|sous-titres?|transcripci[oó]n)\b[^\n]*\n[\s\S]*?(?=\n#{1,3}\s+\S|$)/gi, '\n');
  return s.replace(/\n{3,}/g, '\n\n').trim();
}
const contenu = stripTranscriptSectionsMd(body_content);
md += '## Contenu\n\n' + contenu + '\n\n';
if (transcript_ok && transcript) {
  md += '## Transcript\n\n' + transcript + '\n\n';
}
if (has_image && filename) {
  md += '![screenshot](https://n8n.example.com/media/' + filename + '.png)\n\n';
}
if (kdrive_url) {
  md += '[Voir sur kDrive](' + kdrive_url + ')\n';
}

return [{
  json: {
    title,
    summary,
    tags,
    tags_topic,
    author,
    medium,
    format,
    ocr,
    filename,
    source_url,
    vacuum_ok,
    transcript,
    transcript_ok,
    transcript_source,
    notion_url: notion.url || '',
    kdrive_url,
    markdown: md,
  },
}];
